    confidence = st.selectbox("Confidence Level", ["90%", "95%", "99%"])
    z = 1.645 if confidence == "90%" else 2.576 if confidence == "99%" else 1.96
    p = 0.5
    e = margin / 100
    n0 = (z * z * p * (1 - p)) / (e * e)
    n = math.ceil(n0 / (1 + (n0 - 1) / pop))
