    uploaded = st.file_uploader("Upload PDF or Word Document", type=["pdf", "docx"], key="v6_doc")
    doc_title = st.text_input("Document Title (Optional)", placeholder="e.g. My Thesis Chapter 2 - Land Use in Kumasi")
    focus = st.selectbox("What do you want AI to focus on?", ["Full Brief - Summary + Professional Brief + Questions", "Summary Only - Simple Understanding", "Exam Prep - Questions Lecturer Will Ask", "Thesis Help - Problem + Objective + Next Steps"])
    if uploaded is not None and remaining > 0:
        st.write("File: " + uploaded.name + " | Size: " + str(round(uploaded.size/1024, 1)) + " KB")
        if st.button("Generate Humanized Professional Brief"):
            with st.spinner("AI is reading your document... Please wait 10 seconds..."):
                if uploaded.name.endswith(".pdf"):
                    raw = extract_text_from_pdf(uploaded)
                else:
                    raw = extract_text_from_docx(uploaded)
                if len(raw) < 50:
                    st.error("Could not read this file. Try another PDF or Word file with text (not scanned image).")
                else:
                    new_used = add_upload_count(st.session_state.username)
                    new_remaining = 5 - new_used
                    brief = make_humanized_brief(raw, town, district, region, st.session_state.username)
                    st.markdown(brief)
                    st.success(f"Brief generated! You have {new_remaining} uploads left.")
                    st.download_button("Download Brief as Text", brief, file_name="Brief_" + st.session_state.username + ".txt")
    elif uploaded is not None and remaining <= 0:
        st.error("No uploads left. Please upgrade.")